import pandas as pd,numpy as np
w=pd.read_parquet('works.parquet');c='count__domains__DISTANCE_TRAVEL'
w['r']=w[c]/w.n_passages; w['late']=w.year>=1876
print(pd.crosstab(w.genre,w.late))
def est(d):
  g=d.groupby(['genre','late']).r.mean().unstack(); g=g.dropna(); return (g[True]-g[False]).mean(), g
e,g=est(w);print(e);print(g)
rng=np.random.default_rng(0)
def boot(d,B=2000):
  gs={k:(v[~v.late].r.values,v[v.late].r.values) for k,v in d.groupby('genre')}
  gs={k:v for k,v in gs.items() if len(v[0]) and len(v[1])}
  out=[np.mean([rng.choice(b,len(b)).mean()-rng.choice(a,len(a)).mean() for a,b in gs.values()]) for _ in range(B)]
  return np.percentile(out,[2.5,97.5])
print(boot(w))
for name,d in [('high',w[w.date_confidence=='high']),('nohighlow',w[w.date_confidence!='low']),('noOtherColl',w[~w.genre.isin(['other','collection'])]),('1850-1900',w[(w.year>=1850)&(w.year<1900)])]:
  print(name,est(d)[0],boot(d,1000))
print(w.groupby('decade').r.agg(['mean','size']))
